func:
// Build a Claude Messages API request from the air-quality reading
const aq = msg.payload.current;
msg.aq = aq;
msg.url = "https://api.anthropic.com/v1/messages";
msg.method = "POST";
msg.headers = {
    "content-type": "application/json",
    "x-api-key": env.get("ANTHROPIC_API_KEY"),
    "anthropic-version": "2026-10-21"
};
msg.payload = {
    model: env.get("CLAUDE_MODEL") || "claude-opus-5-5",
    max_tokens: 2048,
    output_config: { effort: "low" },
    system: "คุณคือผู้ช่วยแจ้งเตือนสุขภาพของสำนักงาน ตอบภาษาไทย ไม่เกิน 3 บรรทัด ไม่ใช้ markdown",
    messages: [{
        role: "user",
        content: "ข้อมูลคุณภาพอากาศล่าสุด (ลาดพร้าว): " + JSON.stringify(aq) +
            "\nสรุประดับความเสี่ยง และคำแนะนำสำหรับพนักงานที่จะออกนอกอาคาร"
    }]
};
return msg;

// Pull the text out of Claude's response (content can also hold thinking blocks)
if (msg.statusCode !== 200) {
    node.error("Claude API " + msg.statusCode + ": " + JSON.stringify(msg.payload), msg);
    return null;
}
if (msg.payload.stop_reason === "refusal") {
    node.warn("Claude declined this request");
    return null;
}
const text = msg.payload.content
    .filter(b => b.type === "text")
    .map(b => b.text)
    .join("\n")
    .trim();
flow.set("lastAir", { at: new Date().toISOString(), aq: msg.aq, summary: text });
msg.payload = text;
return msg;

// Payload for the n8n 'notify' webhook (Lab 4)
msg.payload = {
    source: "node-red",
    title: "PM2.5 สูง " + msg.aq.pm2_5 + " µg/m³",
    message: msg.payload
};
msg.headers = { "content-type": "application/json" };
return msg;

// Output 1 → HTTP response, Output 2 → alert (only when too hot)
const { device = "unknown", temp } = msg.payload || {};
if (typeof temp !== "number") {
    msg.statusCode = 400;
    msg.payload = { ok: false, error: "temp ต้องเป็นตัวเลข" };
    return [msg, null];
}
const readings = flow.get("readings") || [];
readings.push({ device, temp, at: new Date().toISOString() });
flow.set("readings", readings.slice(-100));

const alert = temp > 35;
msg.payload = { ok: true, device, temp, alert };
return [msg, alert ? { payload: "🔥 " + device + " อุณหภูมิ " + temp + "°C เกินเกณฑ์ 35°C" } : null];
